input.script:
// Try to dismiss the overlay by removing it
const overlays = document.querySelectorAll('[role="dialog"], [aria-modal="true"]');
overlays.forEach(o => { if (o.offsetParent !== null) o.remove(); });
return overlays.length;

// Find the search input
const searchInput = document.querySelector('input[name="q"]');
if (searchInput) {
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  nativeInputValueSetter.call(searchInput, 'EV charging parking near Smithsonian Institution Washington DC');
  searchInput.dispatchEvent(new Event('input', { bubbles: true }));
  searchInput.dispatchEvent(new Event('change', { bubbles: true }));
  return 'set value';
}
return 'input not found';

// Get all modal/dialog elements and check what's blocking
const dialogs = document.querySelectorAll('[aria-modal="true"], [role="dialog"]');
const result = [];
dialogs.forEach(d => { 
  if (d.offsetParent !== null) {
    result.push({tag: d.tagName, class: d.className, id: d.id});
  }
});
return result;

// Direct click on the place card
const placeCard = document.querySelector('a[aria-label="Washington DC Public Parking"]');
if (placeCard) {
  placeCard.click();
  return 'clicked: ' + placeCard.getAttribute('aria-label');
}
return 'not found';

// Search for the nearest parking location and click it
const cards = document.querySelectorAll('a[aria-label="Colonial Parking"]');
let target = null;
for (const c of cards) {
  const parent = c.closest('div');
  if (parent && parent.innerText.includes('500 C St SW')) {
    target = c;
    break;
  }
}
if (target) {
  target.click();
  return 'clicked: ' + target.getAttribute('aria-label');
}
return 'not found - total: ' + cards.length;

// Get all currently visible dialogs and what's blocking the page
const visibleDialogs = [];
document.querySelectorAll('[aria-modal="true"], [role="dialog"]').forEach(d => {
  if (d.offsetParent !== null) {
    visibleDialogs.push({
      class: d.className,
      ariaLabel: d.getAttribute('aria-label'),
      text: d.innerText.substring(0, 200)
    });
  }
});

// Check what's at the highest z-index
const allElements = document.querySelectorAll('*');
let maxZ = 0;
let topEls = [];
allElements.forEach(el => {
  const style = window.getComputedStyle(el);
  const z = parseInt(style.zIndex);
  if (!isNaN(z) && z > maxZ && el.offsetParent !== null && el.innerText.length > 50) {
    maxZ = z;
    if (topEls.length > 5) topEls.shift();
    topEls.push({tag: el.tagName, class: el.className.substring(0, 80), text: el.innerText.substring(0, 100)});
  }
});
return {dialogs: visibleDialogs, topElements: topEls, maxZ: maxZ};

// Remove empty overlays
document.querySelectorAll('.U5xfxc, .aunsdd').forEach(el => el.remove());

// Get the URL state
return {url: window.location.href, title: document.title};

// Click on Ace Parking
const links = document.querySelectorAll('a[aria-label="Ace Parking"]');
const aceLink = links[0];
if (aceLink) {
  aceLink.click();
  return 'Clicked Ace Parking';
}
return 'no link found';

// Find and click on Ace Parking entry
const aceLinks = document.querySelectorAll('a[aria-label="Ace Parking"]');
if (aceLinks.length > 0) {
  aceLinks[0].scrollIntoView({behavior: 'instant', block: 'center'});
  return 'Found ' + aceLinks.length + ' Ace Parking links';
}
return 'No Ace Parking link found';
